begin;
create table public.retention_policies(id uuid primary key default gen_random_uuid(),record_type text not null unique,retention_days integer not null check(retention_days between 30 and 3650),archive_before_delete boolean not null default true,storage_evidence_required boolean not null default false,active boolean not null default true,owner_user_id uuid not null references auth.users(id),rationale text not null,version integer not null default 1,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create table public.legal_holds(id uuid primary key default gen_random_uuid(),entity_type text not null,entity_id uuid,scope_reason text not null,status text not null default'active'check(status in('active','released')),placed_by uuid not null references auth.users(id),placed_at timestamptz not null default now(),released_by uuid references auth.users(id),released_at timestamptz,release_reason text);
create unique index legal_holds_active_uidx on public.legal_holds(entity_type,coalesce(entity_id,'00000000-0000-0000-0000-000000000000'::uuid))where status='active';
create table public.archival_runs(id uuid primary key default gen_random_uuid(),record_type text not null,cutoff_at timestamptz not null,status text not null check(status in('preview','completed','blocked')),candidate_count integer not null default 0,held_count integer not null default 0,archived_count integer not null default 0,export_authorization_event_id uuid references public.audit_events(id),storage_evidence text,reason text not null,executed_by uuid references auth.users(id),created_at timestamptz not null default now(),completed_at timestamptz);
alter table public.retention_policies enable row level security;alter table public.legal_holds enable row level security;alter table public.archival_runs enable row level security;revoke all on public.retention_policies,public.legal_holds,public.archival_runs from public,anon,authenticated;grant all on public.retention_policies,public.legal_holds,public.archival_runs to service_role;
insert into public.retention_policies(record_type,retention_days,storage_evidence_required,owner_user_id,rationale,updated_by)select x.t,x.d,x.s,sr.user_id,x.r,sr.user_id from(values('bookings',2555,true,'Retain travel and financial evidence for seven years.'),('enquiries',730,false,'Retain non-converted enquiry history for two years.'),('audit_events',2555,false,'Retain accountability evidence for seven years.'),('documents',2555,true,'Database backup does not restore deleted Storage objects.'))x(t,d,s,r)cross join lateral(select sr.user_id from public.staff_roles sr join public.staff_profiles sp on sp.user_id=sr.user_id and sp.active where sr.role::text='owner'order by sr.created_at limit 1)sr;
create function public.preview_retention_archive(p_record_type text)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare v_actor uuid:=auth.uid();v_policy public.retention_policies%rowtype;v_cutoff timestamptz;v_candidates integer;v_held integer;v_run uuid;begin if v_actor is null or not public.is_admin()then raise exception'Owner/admin access required';end if;select*into v_policy from public.retention_policies where record_type=lower(btrim(p_record_type))and active;if not found then raise exception'Active retention policy not found';end if;v_cutoff:=now()-make_interval(days=>v_policy.retention_days);if v_policy.record_type='bookings'then select count(*)into v_candidates from public.bookings where archived_at is not null and archived_at<v_cutoff;elsif v_policy.record_type='enquiries'then select count(*)into v_candidates from public.enquiries where status='closed'and updated_at<v_cutoff;elsif v_policy.record_type='documents'then select count(*)into v_candidates from public.documents where created_at<v_cutoff;else select count(*)into v_candidates from public.audit_events where created_at<v_cutoff;end if;select count(*)into v_held from public.legal_holds where status='active'and entity_type in(v_policy.record_type,'all');insert into public.archival_runs(record_type,cutoff_at,status,candidate_count,held_count,reason,executed_by)values(v_policy.record_type,v_cutoff,case when v_held>0 then'blocked'else'preview'end,v_candidates,v_held,'Retention preview only; no records deleted.',v_actor)returning id into v_run;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata)values(v_actor,'retention.previewed','archival_run',v_run,jsonb_build_object('record_type',v_policy.record_type,'candidate_count',v_candidates,'held_count',v_held));return jsonb_build_object('run_id',v_run,'record_type',v_policy.record_type,'cutoff_at',v_cutoff,'candidate_count',v_candidates,'held_count',v_held,'storage_evidence_required',v_policy.storage_evidence_required,'destructive_action',false);end$$;
create function public.complete_archival_run(p_run_id uuid,p_export_event_id uuid,p_storage_evidence text,p_reason text)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare v_actor uuid:=auth.uid();v_run public.archival_runs%rowtype;v_policy public.retention_policies%rowtype;begin if v_actor is null or not public.is_admin()then raise exception'Owner/admin access required';end if;select*into v_run from public.archival_runs where id=p_run_id for update;if not found or v_run.status<>'preview'then raise exception'Runnable preview not found';end if;select*into v_policy from public.retention_policies where record_type=v_run.record_type;if p_export_event_id is null or not exists(select 1 from public.audit_events where id=p_export_event_id and event_type='report.export_authorized')then raise exception'Valid export authorization is required';end if;if v_policy.storage_evidence_required and char_length(btrim(coalesce(p_storage_evidence,'')))<10 then raise exception'Off-site storage evidence is required';end if;if char_length(btrim(coalesce(p_reason,'')))<10 then raise exception'Archival completion reason is required';end if;if exists(select 1 from public.legal_holds where status='active'and entity_type in(v_run.record_type,'all'))then raise exception'Active legal hold blocks archival';end if;update public.archival_runs set status='completed',export_authorization_event_id=p_export_event_id,storage_evidence=nullif(btrim(coalesce(p_storage_evidence,'')),''),reason=btrim(p_reason),archived_count=candidate_count,completed_at=now()where id=p_run_id;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata)values(v_actor,'retention.archive_completed','archival_run',p_run_id,jsonb_build_object('record_type',v_run.record_type,'candidate_count',v_run.candidate_count,'records_deleted',0));end$$;
create function public.list_retention_governance()returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select case when public.is_admin()then jsonb_build_object('policies',(select coalesce(jsonb_agg(to_jsonb(p)order by p.record_type),'[]')from public.retention_policies p),'legal_holds',(select coalesce(jsonb_agg(to_jsonb(h)order by h.placed_at desc),'[]')from public.legal_holds h),'runs',(select coalesce(jsonb_agg(to_jsonb(r)order by r.created_at desc),'[]')from(select*from public.archival_runs order by created_at desc limit 100)r))else'{}'::jsonb end$$;
revoke execute on function public.preview_retention_archive(text),public.complete_archival_run(uuid,uuid,text,text),public.list_retention_governance()from public,anon;grant execute on function public.preview_retention_archive(text),public.complete_archival_run(uuid,uuid,text,text),public.list_retention_governance()to authenticated,service_role;
commit;
